"""Present audited accounting identities and official IIP compilation-weight checks."""
from __future__ import annotations
import base64
import html
import json
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'outputs/reconciliation'


def table(frame: pd.DataFrame,columns: dict)->str:
    return '<div class="scroll">'+frame[list(columns)].rename(columns=columns).to_html(index=False,border=0,classes='compact',float_format=lambda v:f'{v:,.4f}',escape=True)+'</div>'


def dl(name: str,label: str)->str:
    path=OUT/name
    mime='application/json' if path.suffix=='.json' else 'text/csv'
    return f'<a href="data:{mime};base64,{base64.b64encode(path.read_bytes()).decode()}" download="{name}">{html.escape(label)} ↓</a>'


def build_reconciliation_report()->Path:
    va=json.loads((OUT/'va_summary.json').read_text())
    iip=json.loads((OUT/'iip_reconciliation_summary.json').read_text())
    identities=pd.read_csv(OUT/'va_identity_summary.csv')
    chosen=identities[identities.identity.isin(['broad11_plus_dwellings','detailed19_plus_dwellings','gva_plus_taxes'])].copy()
    chosen['source']=chosen.source.map({'real_nsa':'Real CVM · NSA','real_sa':'Real CVM · SA','current_price_nsa':'Current prices · NSA'})
    overview=table(chosen,{'source':'Source / adjustment','label':'Identity checked','latest_gap_million':'Latest residual · S$m','max_abs_gap_million':'Largest |residual| · S$m','n_quarters':'Quarters','all_within_rounding':'All dates within rounding?'})
    taxonomy=pd.read_csv(OUT/'va_taxonomy.csv',dtype={'broad_id':str,'detailed_id':str})
    taxonomy=taxonomy[taxonomy.source.eq('real_sa')]
    taxonomy_table=table(taxonomy,{'broad_sector':'Broad sector','detailed_sector':'Detailed sector','level_start':'Levels begin','first_qoq_from_full_raw':'First QoQ','first_yoy_from_full_raw':'First YoY'})
    weightchecks=pd.read_csv(OUT/'iip_weight_checks.csv')
    weights=pd.read_csv(OUT/'iip_weights.csv',dtype={'sector_id':str,'parent_id':str})
    current=weights[weights.effective_year.eq(weights.effective_year.max())]
    weighttable=table(current,{'sector':'Cluster / industry','parent_id':'Parent ID','weight_pct_total_manufacturing':'Published weight · % of manufacturing','normalized_weight_within_parent':'Normalized within parent'})
    overlap=pd.read_csv(OUT/'iip_annual_overlap_summary.csv',dtype={'parent_id':str})
    totals=overlap[overlap.parent_id.eq('1')]
    overlap_table=table(totals,{'effective_year':'Weight year','months':'Months checked','max_absolute_error_index_points':'Max |residual| · index points','months_outside_conservative_rounding_interval':'Months outside rounding bounds','known_rebase_vintage_mismatch':'Known vintage mismatch?'})
    two=pd.read_csv(OUT/'iip_two_stage_summary.csv')
    twotable=table(two,{'effective_year':'Weight year','months':'Months checked','max_absolute_error_index_points':'Max |18-leaf → total residual|','months_outside_conservative_rounding_interval':'Outside rounding bounds','known_rebase_vintage_mismatch':'Known vintage mismatch?'})
    png='data:image/png;base64,'+base64.b64encode((OUT/'va_reconciliation.png').read_bytes()).decode()
    body=f'''<main><div class="eyebrow">Singapore / Accounting and index construction</div><h1>Do the components reconcile?</h1>
<p>Check the classification, accounting boundary, index formula and vintage before treating a panel average as the national economy. These checks use cached official releases and retain the residuals.</p>
<div class="callout"><strong>VA:</strong> the 11 broad sectors plus ownership of dwellings reconcile to current-price GVA within rounding. Chained real VA is non-additive. <strong>IIP:</strong> the annual-overlap formula reproduces the total and child hierarchies within conservative display-rounding bounds in recovered matching years. The old-base 2025 weights are flagged as a mismatch. National regressions use the published official aggregates.</div>
<h2>Value added: complete boundary, different price concepts.</h2><p>Our economic-activity panel has 11 broad or 19 detailed sectors. It omits ownership of dwellings; GVA includes dwellings. GDP adds taxes on products to GVA. These boundaries are checked separately. All three VA sources share the 11 August 2026 update and SSIC 2020 classification.</p>
{overview}<p class="notes">Residual = sum of components − published total. Latest quarter: 2026Q2. Current-price complete identities have maximum quarterly discrepancies of S$0.1m. Real chained-2015 series generally do not add up, as SingStat’s table footnotes state. Seasonally adjusted real components need not add either; Singapore introduced direct seasonal adjustment of these series with its 2019 benchmarking changes. The reference-year annual NSA identity is checked; a quarterly reference-year identity is not imposed.</p>
<img src="{png}" alt="VA component reconciliation residuals across time, separating current-price and chain-volume sources" style="width:100%;height:auto"><p class="downloads">{dl('va_quarterly.csv','All quarterly identities')} · {dl('va_annual.csv','Annual identities')} · {dl('va_verification.json','Independent VA arithmetic checks')}</p>
<details><summary>Detailed VA taxonomy · non-overlapping 19-sector cut</summary>{taxonomy_table}<p class="notes">Wholesale and retail are separate, as are accommodation and food services, real estate / professional / administrative services, and the five other-service groups. Parents and children are never stacked into the same panel. Detailed-level coverage begins in 2005Q1; the new four-outcome comparisons use 2006Q1 onward for a common YoY-ready sample.</p>{dl('va_taxonomy.csv','Download full sector mapping')}</details>
<details><summary>Current-price shares and contributions</summary><p>These are additive nominal accounting checks, not real growth contributions. Current-price VA shares should not be substituted into an unqualified sum of chain-linked real levels or log growth rates.</p>{dl('va_annual_current_price_shares.csv','Nominal annual shares')} · {dl('va_annual_nominal_growth_contributions.csv','Additive nominal growth contributions')}</details>
<h2>IIP: annual chain weights, six clusters and 18 industries.</h2><p>IIP is a production index, not value added. The current series is 2025=100 and SSIC 2025. The <a href="https://www.edb.gov.sg/content/dam/edb-en/about-edb/media-releases/manufacturing-statistics/chain_linking_of_monthly_index_of_industrial_production/Memorandum%20of%20Rebase%20%282025100%29.pdf">EDB rebasing memorandum</a> describes unlinked child volume indices, weighted parent aggregation and annual chaining; the 2025 rebase uses the 2024 Census of Manufacturing Activities. Annual chain-linking started in 2019; earlier fixed-base segments are linked into the historical series.</p>
<pre>I_parent(y,m) ≈ mean_previous_year(I_parent)
                × Σ_child [ w_child,y × I_child(y,m) / mean_previous_year(I_child) ]</pre>
<p class="notes">This conditional annual-overlap calculation requires the correct effective-year compilation weights, hierarchy and index vintage. Displayed weights are rounded to 0.1 percentage points. For each parent we normalize its displayed children transparently, retain the resulting error, and compare conservative bounds that allow weight and published-index rounding. We do not infer weights by fitting them to the published total.</p>
{overlap_table}<p class="notes">These total checks use the six published cluster series. A small nonzero residual is expected with rounded inputs. Compatibility with conservative outer bounds supports the calculation but does not recover exact unpublished weights. The 2025 row uses a January 2025 release compiled on the previous 2019 base; it cannot be applied as if it were the current re-estimated 2025 weight vintage.</p>
<h3>Do the subclusters also reach the total?</h3>{twotable}<p class="notes">This second calculation chains 18 leaf industries into their six parents, then combines those reconstructed parents into total manufacturing. The hierarchy is complete and non-overlapping; “total excluding biomedical” is an overlapping aggregate and is excluded from the child list. All recovered displayed parent-weight sums fit their rounding allowances ({len(weightchecks)} checks). Checks concern NSA series; SA additivity is not imposed.</p>
<details><summary>Latest recovered official weights · {int(current.effective_year.max())}</summary>{weighttable}<p class="notes">Weights shown are percentages of total manufacturing. The final column normalizes within each parent for the diagnostic calculation. These annual compilation weights are distinct from the time-varying volume shares needed to aggregate within-year arithmetic growth factors; log growth is not an exact fixed-weight sum of child log growth.</p>{dl('iip_weights.csv','All recovered weight vintages')} · {dl('iip_hierarchy.csv','Parent–child mapping')} · {dl('iip_weight_checks.csv','Displayed-weight sum checks')}</details>
<details><summary>Coverage, growth aggregation and verification evidence</summary><p>Recovered release weights cover 2022, 2023, 2024, 2025 and 2026, with the stated 2025 vintage problem. We have not recovered a complete set of historical compilation weights for the full estimation period. Census VA shares are retained for context, not substituted for actual IIP weights. The published total is therefore used for all national weighted regressions. Industry panel slopes continue to weight units equally and are labelled accordingly.</p><p>The quarterly NSA series separately matches arithmetic means of three monthly levels across {iip['quarterly_monthly_mean_audit_reused']['cells']:,} cells, with maximum rounding gap {iip['quarterly_monthly_mean_audit_reused']['max_abs_index_gap']:.6f} index points. Quarterly SA regressions likewise average monthly SA levels before taking growth.</p>{dl('iip_reconciliation_summary.json','Reconciliation summary')} · {dl('iip_parent_comparisons.csv','Fixed-weight diagnostic residuals')} · {dl('iip_annual_overlap_candidates.csv','Annual-overlap residuals and bounds')} · {dl('iip_two_stage_annual_overlap.csv','Two-stage 18-industry calculation')} · {dl('iip_within_year_growth.csv','Within-year growth aggregation')} · {dl('iip_derived_volume_shares.csv','Derived previous-period volume shares')} · {dl('iip_evidence.json','Official source evidence')}</details>
<h2>How these checks affect the regressions.</h2><p>Aggregate real VA uses SingStat’s published GVA; aggregate manufacturing uses the official weighted total IIP. Broad and detailed panels answer an equal-sector question. A detailed panel assigns one row to each leaf and therefore changes broad-parent weights; matching dates removes a sample-window difference, not that reweighting. We retain these as separate analyses rather than forcing an accounting identity onto regression coefficients.</p>
<p>Common-slope panel errors cluster by sector or industry i. National total regressions have a single unit and retain time-series HAC. Fully sector-specific slopes also retain calendar HAC because a slope supported by one cluster has no usable sector-clustered variance.</p>
<footer><a href="heat_economy.html">Complete tabbed analysis</a> · <a href="granular_va.html">Detailed VA results</a> · <a href="manufacturing_detail.html">Manufacturing results</a><p>Official sources: <a href="https://tablebuilder.singstat.gov.sg/table/TS/M015651">Current-price GDP by industry</a> · <a href="https://tablebuilder.singstat.gov.sg/table/TS/M015661">Real GDP by industry</a> · <a href="https://tablebuilder.singstat.gov.sg/table/TS/M355381">Monthly IIP</a> · <a href="https://www.singstat.gov.sg/files/6448c773-d7c9-4798-9ac7-68ba46e19efb.pdf">2015-reference-year national accounts methodology</a>. Full notes and provenance are embedded in Methods & sources.</p></footer></main>'''
    style='''*{box-sizing:border-box}body{margin:0;background:#f3f7fa;color:#15334a;font:14px/1.7 "Avenir Next","Segoe UI",Arial,sans-serif}main{max-width:1320px;padding:30px 32px;margin:auto}h1,h2,h3{font-family:"Avenir Next Condensed",Arial,sans-serif;line-height:1.15}h1{font-size:43px}h2{font-size:30px;margin-top:36px}h3{font-size:23px}.eyebrow{font:11px Menlo,monospace;color:#64798b;text-transform:uppercase;letter-spacing:1px}a{color:#1f77b4}.callout{padding:17px 20px;background:#e9f3fa;border-left:3px solid #1f77b4;margin:24px 0}.scroll{overflow:auto;background:white;border:1px solid #dbe4eb;border-radius:8px;margin:20px 0}.compact{border-collapse:collapse;width:100%;font-size:12px}.compact td,.compact th{padding:12px;border-bottom:1px solid #dbe4eb;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.compact td:first-child,.compact th:first-child{text-align:left;white-space:normal;min-width:150px}.compact th{color:#64798b;text-align:left}.notes,.downloads,footer{font-size:12px;color:#64798b}pre{font:12px/1.8 Menlo,monospace;white-space:pre-wrap;padding:18px;background:white;border:1px solid #dbe4eb}details{margin:24px 0;padding-top:16px;border-top:1px solid #dbe4eb}summary{font-weight:600;cursor:pointer}footer{margin-top:35px;border-top:1px solid #dbe4eb;padding-top:20px}@media(max-width:700px){main{padding:20px 16px}h1{font-size:35px}}'''
    path=ROOT/'outputs/reconciliation.html'
    path.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aggregate VA and IIP reconciliation</title><style>'+style+'</style></head><body>'+body+'</body></html>')
    print('Wrote reconciliation.html')
    return path

if __name__=='__main__': build_reconciliation_report()
